llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "S-verapamil, the closest high-similarity analogue sharing the dimethoxyphenethylamine and tertiary amine core, has an absolute oral bioavailability of approximately 20% in humans, placing it at the F≥20% threshold and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "In normal subjects, d3-verapamil showed a mean absolute bioavailability of 22.0%, above the 20% threshold, providing direct evidence that verapamil-like scaffolds can meet the high-F criterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Verapamil absolute bioavailability was 35% ± 7% after a 120 mg oral dose in healthy subjects, well above 20%, supporting high F for the closely related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Gallopamil, a verapamil analogue with the same dimethoxyphenethylamine core, exhibited 96.3% oral bioavailability in humans, showing that modest structural changes in this scaffold can yield high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Vernakalant, which shares the dimethoxyphenethylamine and basic tertiary amine features, has ~60% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "A verapamil study reported mean oral bioavailability of only 10.5%, demonstrating that first-pass metabolism can lower F below 20% in this scaffold; this contradictory evidence is outweighed by the preponderance of higher-F measurements.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tetrabenazine, a dimethoxy-substituted cyclic amine/ketone, had very low systemic availability (~4.9%), but its extensive ketone-reduction first-pass metabolism and rigid lipophilic structure are not directly applicable to the query's lactam/amide and flexible amine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable experimental evidence—verapamil and its close analogues—indicates absolute oral bioavailability at or above 20% in most studies (20–35%, with gallopamil at 96% and vernakalant at ~60%). The lower-F analogues are less similar and have distinct metabolic/solubility liabilities. Therefore the query is predicted high for F≥20%, with moderate confidence.",
  "evidence_gaps": [
    "No direct bioavailability measurement for the exact query molecule.",
    "Verapamil F values vary widely (10–52%) due to first-pass metabolism and formulation, making the threshold decision somewhat sensitive.",
    "The effect of the cyclic lactam/amide on permeability and first-pass metabolism is not directly evidenced.",
    "The low neutral fraction at pH 7.4 could lower absorption, but this is not experimentally confirmed for this scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

